class Solution:
    def getSumAbsoluteDifferences(self, nums: List[int]) -> List[int]:
        n = len(nums)
        total = sum(nums)
        s1 = 0
        s2 = total
        arr = []
        for i in range(n):
            arr.append(self.calculateAbsoluteDifference(s1, nums[i], i, s2, n))
            s1 += nums[i]
            s2 = total - s1
        return arr

    def calculateAbsoluteDifference(self, s1, x, i, s2, n):
        return abs(s1 + x - s2 - (i + 1) * x) + abs(s1 - s2 + (i + 1) * x)
